    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نوحّد المقامات","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">10</span></span> - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">10</span></span> + <span class=\"frac\"><span class=\"num\">10</span><span class=\"den\">10</span></span></span>"},{"quoi":"تنبيه","math":"لا يُجمع كسران قبل توحيد المقامَين، و المقام المشترك ليس دائما جداء المقامَين"},{"quoi":"نجمع البسوط","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"تنبيه","math":"النتيجة تُترك دائما في أبسط صورة — كسرا غير قابل للاختزال"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض بقيمة A","math":"<span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> = 0</span>"},{"quoi":"القاعدة","math":"العددان اللذان مجموعهما صفر متقابلان"},{"quoi":"نكتب المقابل","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"}],
