    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (x - y - <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span>) = -x + y + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span></span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المسبوق بعلامة الجمع","math":"<span dir=\"ltr\" class=\"expr\">+ (x - y) = + x - y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = x - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - x + y + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span> + x - y - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">10</span></span></span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = (x - x + x) + (y - y) + (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">10</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">10</span></span> = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = 2</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 2 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>) - (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span>)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span></span>"}],
