    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -2 - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-2 - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> = -<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (a + 2 - b) = -a - 2 + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المسبوق بعلامة الجمع","math":"<span dir=\"ltr\" class=\"expr\">+ (-4 + a) = -4 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 9 - a - 2 + b - 4 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + a) + b + (9 - 2 - 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">9 - 2 - 4 = 3</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b + 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>) - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">47</span><span class=\"den\">10</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b + 3</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 3 = -8</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-8) - 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -11</span>"}],
