    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -3 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-3 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-3 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> = -<span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (a + 5 - b) = -a - 5 + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المسبوق بعلامة الجمع","math":"<span dir=\"ltr\" class=\"expr\">+ (-4 + a) = -4 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 3 - a - 5 + b - 4 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + a) + b + (3 - 5 - 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">3 - 5 - 4 = -6</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = -2</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = (-2) - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">4</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 6</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) - 6 = -1</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-1) - (-6)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = 5</span>"}],
