    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">E = -6 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + a</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 1</span> <span dir=\"ltr\" class=\"expr\">F = 5 - (a + 3 - b) + (-3 + a)</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 1</span> احسب <span dir=\"ltr\" class=\"expr\">E</span> في حالة <span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span> <span dir=\"ltr\" class=\"expr\">E = -6 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + a</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 1</span> احسب <span dir=\"ltr\" class=\"expr\">E</span> في حالة <span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span> أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">F = -7</span> و <span dir=\"ltr\" class=\"expr\">F = b - 1</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -6 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-6 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = -<span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (a + 3 - b) = -a - 3 + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المسبوق بعلامة الجمع","math":"<span dir=\"ltr\" class=\"expr\">+ (-3 + a) = -3 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 5 - a - 3 + b - 3 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + a) + b + (5 - 3 - 3)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 - 3 - 3 = -1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 1</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">20</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">6</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 1</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) - 1 = -7</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-7) - (-1)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -6</span>"}],
