    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">a - (1 - b) = a - 1 + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [a - 1 + b] = -a + 1 - b</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 1) = a - 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = a - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> - a + 1 - b + a - 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (a - a + a) - b + (-<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> + 1 - 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> + 1 - 1 = -<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = -3</span> و <span dir=\"ltr\" class=\"expr\">b = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = (-3) - (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>) - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">109</span><span class=\"den\">20</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(a - b) - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> = -1</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">a - b = (-1) - (-<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span>)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - b = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">a - b - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> = 0</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">a - b = <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">5</span></span> &gt; 0</span>"},{"quoi":"القاعدة","math":"الفرق موجب، إذن a أكبر من b"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a &gt; b</span>"}],
