    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">(-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span>) + (-b - 0,7) = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> - b - 0,7</span>"},{"quoi":"نرفع القوسين الباقيين","math":"<span dir=\"ltr\" class=\"expr\">E = 2 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> + b + 0,7 + 0,8 + a</span>"},{"quoi":"نجمّع المجهولين","math":"<span dir=\"ltr\" class=\"expr\">E = (a + b) + (2 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> + 0,7 + 0,8)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> + 0,7 + 0,8 = <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">5</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">26</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">3 - [a + (-<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span>)] = 3 - a + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span></span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (3,1 + b) = -3,1 - b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 3 - a + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> - 3,1 - b</span>"},{"quoi":"نجمّع المجهولين","math":"<span dir=\"ltr\" class=\"expr\">F = -(a + b) + (3 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> - 3,1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">3 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> - 3,1 = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نترجم « متقابلان »","math":"<span dir=\"ltr\" class=\"expr\">b = -a</span>"},{"quoi":"نحسب المجموع","math":"<span dir=\"ltr\" class=\"expr\">a + b = a + (-a) = 0</span>"},{"quoi":"نستعمل الشكل المبسّط","math":"<span dir=\"ltr\" class=\"expr\">E = (a + b) + <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">5</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = 0 + <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">22</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى","math":"<span dir=\"ltr\" class=\"expr\">b = a</span>"},{"quoi":"نحسب المجموع","math":"<span dir=\"ltr\" class=\"expr\">a + b = a + a = 2a</span>"},{"quoi":"نستعمل الشكل المبسّط","math":"<span dir=\"ltr\" class=\"expr\">F = -(a + b) + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = -(2a) + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة بدلالة a","math":"<span dir=\"ltr\" class=\"expr\">F = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">10</span></span> - 2a</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">5 - x - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> = -4</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">5</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">5</span></span> - x = -4</span>"},{"quoi":"المجهول هو الفرق","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">5</span></span> - (-4)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">43</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">-4 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - x = -1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> = -<span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">4</span></span> - x = -1</span>"},{"quoi":"المجهول هو الفرق","math":"<span dir=\"ltr\" class=\"expr\">x = (-<span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">4</span></span>) - (-1)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>7)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|x| = 2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span></span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span> = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">10</span></span></span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">10</span></span> &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد كسري نسبي x يحقّق المعادلة"}],
